import React, { useEffect, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { FiArrowLeft, FiPlus } from "react-icons/fi";
import DashboardLayout from "../../layouts/DashboardLayout";
import Card from "../../components/Card";
import DataTable from "../../components/DataTable";
import Loading from "../../components/Loading";
import { studentApi } from "../../api/studentApi";
import { gradeApi } from "../../api/gradeApi";
import { useToast } from "../../context/ToastContext";
import { extractErrorMessage } from "../../api/axios";
import { fullName, gpaRemark } from "../../utils/formatters";

export default function StudentGrades() {
  const { id } = useParams();
  const navigate = useNavigate();
  const toast = useToast();

  const [student, setStudent] = useState(null);
  const [grades, setGrades] = useState([]);
  const [gpa, setGpa] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    setIsLoading(true);
    Promise.allSettled([studentApi.getOne(id), gradeApi.getByStudent(id), gradeApi.getGpa(id)]).then(
      ([studentRes, gradesRes, gpaRes]) => {
        if (studentRes.status === "fulfilled") {
          setStudent(studentRes.value.data?.data || studentRes.value.data);
        } else {
          toast.error(extractErrorMessage(studentRes.reason, "Student not found."));
          navigate("/grades");
          return;
        }
        if (gradesRes.status === "fulfilled") {
          const list = gradesRes.value.data?.data || gradesRes.value.data || [];
          setGrades(Array.isArray(list) ? list : []);
        } else {
          setError(extractErrorMessage(gradesRes.reason, "Unable to load grades."));
        }
        if (gpaRes.status === "fulfilled") {
          setGpa(gpaRes.value.data?.data || gpaRes.value.data);
        }
        setIsLoading(false);
      }
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const columns = [
    { key: "course_code", label: "Course Code", render: (r) => <span className="font-mono text-xs bg-navy-50 text-navy-700 px-2 py-1 rounded">{r.course_code || r.course?.code}</span> },
    { key: "course_name", label: "Course Name", render: (r) => r.course_name || r.course?.name },
    { key: "credit_hour", label: "Credit Hour", render: (r) => r.credit_hour ?? r.course?.credit_hour, hideOnMobile: true },
    { key: "semester", label: "Semester", hideOnMobile: true },
    { key: "academic_year", label: "Academic Year", hideOnMobile: true },
    { key: "grade", label: "Grade", render: (r) => <span className="font-mono text-sm font-semibold text-navy-800 bg-navy-50 px-2.5 py-1 rounded">{r.grade}</span> },
    { key: "remark", label: "Remark", render: (r) => r.remark || "—", hideOnMobile: true }
  ];

  if (isLoading) {
    return (
      <DashboardLayout>
        <Loading label="Loading grade report..." />
      </DashboardLayout>
    );
  }

  const gpaValue = gpa?.gpa ?? gpa?.value;

  return (
    <DashboardLayout>
      <Link to="/grades" className="inline-flex items-center gap-1.5 text-sm text-navy-600 hover:text-navy-800 mb-4">
        <FiArrowLeft size={14} /> Back to Student Search
      </Link>

      <div className="grid lg:grid-cols-3 gap-5">
        {/* GPA card */}
        <Card className="p-6 lg:col-span-1 h-fit">
          <p className="text-xs uppercase tracking-wide text-muted mb-1">Student</p>
          <h1 className="font-display text-lg text-navy-800 mb-1">{student ? fullName(student) : "—"}</h1>
          <p className="font-mono text-xs text-navy-600 mb-6">{student?.registration_number}</p>

          {gpaValue === undefined || gpaValue === null ? (
            <div className="text-center py-8 text-sm text-muted">GPA not available yet.</div>
          ) : (
            <div className="flex flex-col items-center">
              <div className="relative h-36 w-36 flex items-center justify-center">
                <svg viewBox="0 0 120 120" className="h-36 w-36 -rotate-90">
                  <circle cx="60" cy="60" r="52" fill="none" stroke="#E3E7EF" strokeWidth="10" />
                  <circle
                    cx="60"
                    cy="60"
                    r="52"
                    fill="none"
                    stroke="#C89B3C"
                    strokeWidth="10"
                    strokeLinecap="round"
                    strokeDasharray={`${(Number(gpaValue) / 4) * 326.7} 326.7`}
                  />
                </svg>
                <div className="absolute text-center">
                  <p className="text-[11px] text-muted uppercase tracking-wide">Current GPA</p>
                  <p className="font-mono text-3xl text-navy-800 mt-0.5">{Number(gpaValue).toFixed(2)}</p>
                  <p className="text-xs text-gold-600 font-medium mt-0.5">{gpaRemark(gpaValue)}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3 mt-5 w-full text-center">
                <div className="bg-paper rounded-lg py-3">
                  <p className="font-mono text-base text-navy-800">
                    {gpa?.total_credit_hours ?? gpa?.credit_hours ?? "—"}
                  </p>
                  <p className="text-[11px] text-muted mt-1">Total Credit Hours</p>
                </div>
                <div className="bg-paper rounded-lg py-3">
                  <p className="font-mono text-base text-navy-800">{gpa?.quality_points ?? "—"}</p>
                  <p className="text-[11px] text-muted mt-1">Quality Points</p>
                </div>
              </div>
            </div>
          )}
        </Card>

        {/* Grades table */}
        <Card className="lg:col-span-2">
          <div className="flex items-center justify-between p-5 border-b border-line">
            <p className="font-display text-base text-navy-800">Course Grades</p>
            <Link
              to="/grades/assign"
              className="flex items-center gap-1.5 text-xs font-medium bg-navy-700 text-white px-3 py-1.5 rounded-lg hover:bg-navy-800 transition"
            >
              <FiPlus size={13} /> Assign Grade
            </Link>
          </div>
          <DataTable
            columns={columns}
            rows={grades}
            isLoading={false}
            error={error}
            emptyTitle="No grades available for this student."
            emptyDescription="Assign a grade for a registered course to see it here."
            emptyAction={{ label: "Assign Grade", onClick: () => navigate("/grades/assign") }}
          />
        </Card>
      </div>
    </DashboardLayout>
  );
}
